use crate::codec::{byte_decode, byte_decode_12};
use crate::ntt::NTT;
use crate::params::{DU, DV, N, K};
use crate::ring::Poly;

#[allow(unused)]
pub struct DecryptionKey {
    key: [u8; 384 * K],
}

#[allow(unused)]
impl DecryptionKey {
    pub fn new(key: [u8; 384 * K]) -> Self {
        DecryptionKey { key }
    }

    pub(crate) fn key_bytes(&self) -> (&[u8]) {
        &self.key
    }

    pub fn decrypt(&self, c: [u8; 32 * (DU as usize * K + DV as usize)]) -> [u8; 32] {
        let c1: [u8; 32 * DU as usize * K] = c[0..32 * DU as usize * K]
            .try_into()
            .expect("ciphertext 1");
        let c2: [u8; 32 * DV as usize] = c[32 * DU as usize * K..]
            .try_into()
            .expect("ciphertext 2");

        let mut f: [[u16; N]; K] = [[0u16; N]; K];
        for i in 0..K {
            byte_decode(
                &c1[i * 32 * DU as usize..][..32 * DU as usize],
                &mut f[i],
                DU,
            );
        }
        let udh: [NTT; K] = {
            let u_dash: [Poly; K] = f.map(|f_| Poly::from(&f_).decompress::<DU>());
            u_dash.map(|ud| NTT::from_poly(&ud))
        };

        let sh: [NTT; K] = {
            let mut s = [[0u16; N]; K];
            let b = self.key_bytes();
            for i in 0..K {
                byte_decode_12(&b[i * 384..][..384], &mut s[i]);
            }
            s.map(|s| NTT::from(s))
        };

        let v_dash: Poly = {
            let mut vf: [u16; N] = [0u16; N];
            byte_decode(&c2, &mut vf, DV);
            Poly::from(&vf).decompress::<DV>()
        };

        let mut r: NTT = NTT::default();
        for i in 0..K {
            r = r.add(&sh[i].mul(&udh[i]));
        }
        let w = v_dash.sub(&r.inv());

        let m: [u8; 32] = w.compress_1().byte_encode_1();
        m
    }
}

#[cfg(test)]
#[cfg(feature = "ML_KEM_512")]
mod mlkem512_tests {
    use crate::params::{DU, DV, K};
    use crate::{keygen, prf};

    // https://github.com/itzmeanjan/ml-kem/blob/master/kats/ml_kem_512.kat
    #[test]
    fn mlkem512_run_kats() {
        let kat_d = [
            "7c9935a0b07694aa0c6d10e4db6b1add2fd81a25ccb148032dcd739936737f2d",
            "d60b93492a1d8c1c7ba6fc0b733137f3406cee8110a93f170e7a78658af326d9",
            "25056d1b8113bb362dd979d98643d7a7ac9c4f95994c0ba060609b6d07002ff3",
            "aa6dd1e5799cdf7af9c4fc632b3eb9d51d66e85c8e0a21ec98664fc51ab63c7d",
            "195d6c86a3df4c21e3007d7f2768b43c74cb3060e0eca77f0a5d3271542b9a84",
        ];
        let kat_pk_sk = [
            (
                "",
                "",
            ),
            (
                "",
                "",
            ),
            (
                "",
                "",
            ),
            (
                "",
                "",
            ),
            (
                "",
                "",
            ),
        ];
        let kat_m = [
            "eb4a7c66ef4eba2ddb38c88d8bc706b1d639002198172a7b1942eca8f6c001ba",
            "46401015603c5e2174cb94ac742e836b516e2d570f15de0b9d0204d79ac64ba3",
            "c07d2a9f28995f021a974e798a55aec0230b11b9ee542f69925d009159425e81",
            "da9c015b918108c1596309fe0042218de4c31900b8dfa6c1cec28ad10988bbc7",
            "05874f9d5a2e9133d385f3326fa925129dff03359d78b0d07ed78fd5c1307800",
        ];
        let kat_ss = [
            "b4c8e3c4115f9511f2fddb288c4b78c5cd7c89d2d4d321f46b4edc54ddf0eb36",
            "ce6786c31a7daf57e0fc5d3857689fa47240ecbdbbcb3afa315a85bd8db682c8",
            "4ac77ef58bbc83f56c4383c8015dcd3b915cfa16f951e993048be433f3dbdb4a",
            "ea178d59df2f3d75e817125641895e3b208dcf798af6fc9d7263f5f64768ef22",
            "39b5ab6cffe8560e2744c924cea5bdbb377ac4c1ae921e545fd3854bf4c19898",
        ];

        let kat_ct = [
            "",
            "",
            "",
            "",
            "",
        ];

        for i in 0..kat_d.len() {
            let d = hex::decode(kat_d[i]).unwrap();
            let d: [u8; 32] = d.try_into().unwrap();
            let exp_pk: [u8; 800] = hex::decode(kat_pk_sk[i].0).unwrap().try_into().unwrap();
            let exp_sk: [u8; 1632] = hex::decode(kat_pk_sk[i].1).unwrap().try_into().unwrap();
            let (pk, dk, _) = keygen::key_gen(d);
            assert_eq!(pk.key_bytes(), exp_pk);
            assert_eq!(dk.key_bytes(), &exp_sk[0..384 * K]);
            let m: [u8; 32] = hex::decode(kat_m[i]).unwrap().try_into().unwrap();

            let mut hash_ek = [0u8; 32];
            prf::sha3_256(&pk.key_bytes(), &mut hash_ek); // H(ek)
            let mut m_h_ek: [u8; 64] = [0u8; 64];
            m_h_ek[0..32].copy_from_slice(&m);
            m_h_ek[32..].copy_from_slice(&hash_ek);

            let mut hash = [0u8; 64];
            prf::sha3_512(&m_h_ek, &mut hash); // G(m||H(ek))
            let r: [u8; 32] = hash[32..].try_into().unwrap();

            let ct = pk.encrypt(m.into(), r);

            let ss: [u8; 32] = hash[0..32].try_into().unwrap();
            let exp_ss: [u8; 32] = hex::decode(kat_ss[i]).unwrap().try_into().unwrap();
            assert_eq!(ss, exp_ss);

            let exp_ct: [u8; 32usize * (DU as usize * K + DV as usize)] =
                hex::decode(kat_ct[i]).unwrap().try_into().unwrap();
            let md = dk.decrypt(exp_ct);

            let ct_dash = pk.encrypt(md.into(), r);
            assert_eq!(ct_dash.len(), ct.len());
            assert_eq!(ct_dash, ct);

            for i in 0..ct.len() {
                if ct[i] != exp_ct[i] {
                    println!("{i} - {} != {}", ct[i], exp_ct[i]);
                }
            }
            assert_eq!(ct, exp_ct, "kat index {i}");
        }
    }
}

#[cfg(test)]
#[cfg(feature = "ML_KEM_768")]
mod mlkem768_cpa_decrypt_tests {
    use crate::params::{DU, DV, K};
    use crate::{keygen, prf};

    #[test]
    fn test_decrypt_00() {
        let d = hex::decode("684a29e4e5480a5f2533e1526b5fac8cdf5927f3d85087c71f928c59690eb565")
            .unwrap();
        let d: [u8; 32] = d.try_into().unwrap();
        let exp_pk: [u8; 1184] = hex::decode("").unwrap().try_into().unwrap();
        let exp_sk: [u8; 2400] = hex::decode("").unwrap().try_into().unwrap();
        let (pk, dk, _) = keygen::key_gen(d);
        assert_eq!(pk.key_bytes(), exp_pk);
        assert_eq!(dk.key_bytes(), &exp_sk[0..384 * K]);

        let m: [u8; 32] =
            hex::decode("492d4cea1c6e07d9535ab2fc21d773bea7ee2c7d66ec80d41191aed269a398d6")
                .unwrap()
                .try_into()
                .unwrap();

        let mut hash_ek = [0u8; 32];
        prf::sha3_256(&pk.key_bytes(), &mut hash_ek); // H(ek)
        let mut m_h_ek: [u8; 64] = [0u8; 64];
        m_h_ek[0..32].copy_from_slice(&m);
        m_h_ek[32..].copy_from_slice(&hash_ek);
        let mut hash = [0u8; 64];

        prf::sha3_512(&m_h_ek, &mut hash); // G(m||H(ek))
        let r: [u8; 32] = hash[32..].try_into().unwrap();

        let ct = pk.encrypt(m.into(), r);
        let exp_ct: [u8; 32usize*(DU as usize * K + DV as usize)] = hex::decode("").unwrap().try_into().unwrap();
        assert_eq!(ct, exp_ct);

        let ss: [u8; 32] = hash[0..32].try_into().unwrap();
        let exp_ss: [u8; 32] =
            hex::decode("a154db38fa0190042b01911ac8ec66a01f704f397e8e134e70cdf4b773a32484")
                .unwrap()
                .try_into()
                .unwrap();
        assert_eq!(ss, exp_ss);

        let md = dk.decrypt(exp_ct);
        let ct_dash = pk.encrypt(md.into(), r);
        assert_eq!(ct_dash.len(), ct.len());
        assert_eq!(ct_dash, ct);
    }

    #[test]
    fn test_decrypt_01() {
        let d = hex::decode("c1b3cbffad4b306f9af0cdd3028876486dbe858875c9b6497fe20172a986c82b")
            .unwrap();
        let d: [u8; 32] = d.try_into().unwrap();
        let exp_pk: [u8; 1184] = hex::decode("").unwrap().try_into().unwrap();
        let exp_sk: [u8; 2400] = hex::decode("").unwrap().try_into().unwrap();
        let (pk, dk, _) = keygen::key_gen(d);
        assert_eq!(pk.key_bytes(), exp_pk);
        assert_eq!(dk.key_bytes(), &exp_sk[0..384 * K]);

        let m: [u8; 32] =
            hex::decode("d70b79de7c2f7cb8d18eaf1ca040f6d8588ba85512ad000b59806ba485538377")
                .unwrap()
                .try_into()
                .unwrap();

        let mut hash_ek = [0u8; 32];
        prf::sha3_256(&pk.key_bytes(), &mut hash_ek); // H(ek)
        let mut m_h_ek: [u8; 64] = [0u8; 64];
        m_h_ek[0..32].copy_from_slice(&m);
        m_h_ek[32..].copy_from_slice(&hash_ek);
        let mut hash = [0u8; 64];

        prf::sha3_512(&m_h_ek, &mut hash); // G(m||H(ek))
        let r: [u8; 32] = hash[32..].try_into().unwrap();

        let ct = pk.encrypt(m.into(), r);
        let exp_ct: [u8; 32usize*(DU as usize * K + DV as usize)] = hex::decode("").unwrap().try_into().unwrap();
        assert_eq!(ct, exp_ct);

        let ss: [u8; 32] = hash[0..32].try_into().unwrap();
        let exp_ss: [u8; 32] =
            hex::decode("9bd6bcc6cb530617cb4d8107bcedac5524b1a39b5b5ed74c124bcb47a0e115c5")
                .unwrap()
                .try_into()
                .unwrap();
        assert_eq!(ss, exp_ss);

        let md = dk.decrypt(exp_ct);
        let ct_dash = pk.encrypt(md.into(), r);
        assert_eq!(ct_dash.len(), ct.len());
        assert_eq!(ct_dash, ct);
    }
}

#[cfg(test)]
#[cfg(feature = "ML_KEM_1024")]
mod mlkem1024_cpa_decrypt_tests {
    use crate::params::{DU, DV, K};
    use crate::{keygen, prf};

    #[test]
    fn test_decrypt_00() {
        let d = hex::decode("d569b935ce015c85f792f8f7fb0d83c4f53b492959361dd4f75fb764d6564501")
            .unwrap();
        let d: [u8; 32] = d.try_into().unwrap();
        let exp_pk: [u8; 1568] = hex::decode("").unwrap().try_into().unwrap();
        let exp_sk: [u8; 3168] = hex::decode("").unwrap().try_into().unwrap();
        let (pk, dk, _) = keygen::key_gen(d);
        assert_eq!(pk.key_bytes(), exp_pk);
        assert_eq!(dk.key_bytes(), &exp_sk[0..384 * K]);

        let m: [u8; 32] =
            hex::decode("adf233a4311b157829d49a0bcb633571230f7060f3ce655551aed8be8961d1ca")
                .unwrap()
                .try_into()
                .unwrap();

        let mut hash_ek = [0u8; 32];
        prf::sha3_256(&pk.key_bytes(), &mut hash_ek); // H(ek)
        let mut m_h_ek: [u8; 64] = [0u8; 64];
        m_h_ek[0..32].copy_from_slice(&m);
        m_h_ek[32..].copy_from_slice(&hash_ek);
        let mut hash = [0u8; 64];

        prf::sha3_512(&m_h_ek, &mut hash); // G(m||H(ek))
        let r: [u8; 32] = hash[32..].try_into().unwrap();

        let ct = pk.encrypt(m.into(), r);
        let exp_ct: [u8; 32usize*(DU as usize * K + DV as usize)] = hex::decode("").unwrap().try_into().unwrap();
        for i in 0..ct.len() {
            if ct[i] != exp_ct[i] {
                println!("ct mismatch-- {}: {} {}", i, ct[i], exp_ct[i]);
            }
        }
        let md = dk.decrypt(exp_ct);
        let ct_dash = pk.encrypt(md.into(), r);
        assert_eq!(ct_dash.len(), ct.len());
        assert_eq!(ct_dash, ct);
        assert_eq!(exp_ct, ct);

        let ss: [u8; 32] = hash[0..32].try_into().unwrap();
        let exp_ss: [u8; 32] =
            hex::decode("30b142fb52346d2955dd0901bdadc20f7f286c002c39c7eccbcbb372a21bbe31")
                .unwrap()
                .try_into()
                .unwrap();
        assert_eq!(ss, exp_ss);
    }
}
